import{_ as n,o,c as a,ai as e}from"./chunks/framework.Ai2o9gNv.js";const s="/assets/AtomCode%E5%BE%AE%E4%BF%A1%E5%B0%8F%E7%A8%8B%E5%BA%8F%E5%85%A8%E6%B5%81%E7%A8%8B%E6%80%BB%E8%A7%88.CWP957js.svg",r="/assets/image-20260609111825689.c3ri5lHx.png",p="/assets/image-20260609111842302.7abv7kUV.png",i="/assets/image-20260609113733740.B_rvyi_l.png",m="/assets/image-20260609113752860.BlvQLSGY.png",g="/assets/image-20260609141737676.Dqq0SLa1.png",d="/assets/%E5%BE%AE%E4%BF%A1%E5%B0%8F%E7%A8%8B%E5%BA%8F%E5%88%9B%E5%BB%BA%E5%8F%91%E5%B8%83%E6%B5%81%E7%A8%8B%E6%80%BB%E8%A7%88.B56vPQFa.svg",c="/assets/image-20260609142743406.cbG-Ox-K.png",l="/assets/image-20260609142800890.zNPkZncg.png",h="/assets/image-20260609144009348.BGkFy_92.png",_="/assets/image-20260609142847397.C4pNQxT8.png",b="/assets/image-20260609142924773.Dg3VRtKm.png",A="/assets/image-20260609142953818.3iwr5RbV.png",q="/assets/image-20260609144138459.Dzeiq7Ig.png",u="/assets/image-20260609144734434.RE0Eq2i-.png",k="/assets/image-20260609145421268.buz2ra0M.png",P="/assets/image-20260615225603472.DNSBxDds.png",f="/assets/image-20260615225739281.DkHci2Mu.png",C="/assets/image-20260615225832408.lwiyvj6J.png",x="/assets/image-20260615230047478.CXnseHrX.png",E="/assets/image-20260615230113921.DtwaaHnR.png",B="/assets/image-20260615230140972.I_TSKBri.png",I="/assets/image-20260615230346109.Cezmzj8o.png",v="/assets/image-20260615230400781.BaxqdFzf.png",V=JSON.parse('{"title":"AtomCode开发微信小程序《谁去呀》 全流程","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/AtomcCode开发微信小程序全流程/AtomCode开发微信小程序全流程.md","filePath":"AI人工智能/AtomcCode开发微信小程序全流程/AtomCode开发微信小程序全流程.md","lastUpdated":1781537572000,"__rawMarkdown":"# AtomCode开发微信小程序《谁去呀》 全流程\\n\\n> 万少：华为HDE、鸿蒙极客\\n>\\n> 个人主页：https://blog.zbztb.cn/\\n>\\n> 2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户500+、鸿蒙免费课程2套。\\n>\\n> 如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。\\n>\\n> 仓库地址：https://atomgit.com/uksri/goOrNot\\n\\n## 流程总览\\n\\n![AtomCode 开发微信小程序全流程总览图](./assets/AtomCode微信小程序全流程总览.svg)\\n\\n\\n\\n\\n\\n## 什么是AtomCode\\n\\n> https://atomcode.atomgit.com/\\n\\n![](assets/image-20260609111825689.png)\\n\\n\\n\\n## 下载安装AtomCode\\n\\n![](assets/image-20260609111842302.png)\\n\\n\\n\\n安装成功后，终端中输入命令，查看版本信息\\n\\n> atomcode --version\\n\\n## AtomCode简单使用\\n\\n### 首次使用\\n\\n首次使用，需要在终端中输入 `atomcode`\\n\\n---\\n\\n**选择语言**\\n\\n![](assets/image-20260609113733740.png)\\n\\n---\\n\\n\\n\\n**选择验证方式**\\n\\n![](assets/image-20260609113752860.png)\\n\\n\\n\\n### 使用技巧\\n\\n在每一个新的工程中，首次执行，都建议执行一次 `/init`，这个命令是让 atomcode 熟悉你的工程，同时也可以把一些项目开发中的约定填写进去，这个文件可以随着项目的推进来更新和维护。\\n\\n后续你可以使用自然语言和atomcode对话来实现你的功能需求；\\n\\n> https://atomcode.atomgit.com/docs/zh/slash-commands.html\\n\\n![](assets/image-20260609141737676.png)\\n\\n## 微信小程序创建-发布流程总览\\n\\n![微信小程序创建到发布流程总览图](./assets/微信小程序创建发布流程总览.svg)\\n\\n\\n\\n## 注册微信小程序开发者账号\\n\\n> https://mp.weixin.qq.com/\\n\\n![](assets/image-20260609142743406.png)\\n\\n---\\n\\n\\n\\n![](assets/image-20260609142800890.png)\\n\\n## 获取微信小程序的APPID\\n\\nAPPID用来开发和发布使用，注册或登录小程序后台后便可以轻松获取。\\n\\n在**管理-开发管理-开发设置**中可以获取小程序的**APPID**\\n\\n![](assets/image-20260609144009348.png)\\n\\n这个id先记住，稍后使用。\\n\\n\\n\\n\\n\\n## 下载微信开发者工具\\n\\n> https://developers.weixin.qq.com/miniprogram/dev/devtools/devtools.html\\n\\n![](assets/image-20260609142847397.png)\\n\\n\\n\\n---\\n\\n下载成功\\n\\n![](assets/image-20260609142924773.png)\\n\\n\\n\\n## 新建微信小程序工程\\n\\n打开微信开发者工具，然后新建项目。\\n\\n\\n\\n![](assets/image-20260609142953818.png)\\n\\n\\n\\n考虑后端的能力，可以选择云开发-最低20元一个月。\\n\\n也可以不选择云开发，如果自己有后端的话，**万少这里选择使用自己的后端能力。**\\n\\n这里可以填写上面保存好的**AppID**。\\n\\n![](assets/image-20260609144138459.png)\\n\\n---\\n\\n万少这里是将小程序和后端放在同一个目录内，方便**atomcode**操作。\\n\\n![](assets/image-20260609144734434.png)\\n\\n## 生成产品原型图\\n\\n考虑到具体要开发的产品，最好是先生成产品的原型图，然后以它作为参考，使用**atomcode**辅助开发小程序端和后端。\\n\\n![](assets/image-20260609145421268.png)\\n\\n\\n\\n## 协同开发客户端和后端\\n\\n这里的开发顺序可以是：\\n\\n1. **优先开发大部分小程序端的功能，包括页面设计、基本交互等，如果涉及和后端交互的数据，可以让atomcode在小程序端先使用模拟数据。**\\n2. **待小程序端开发差不多后，可以进行后端功能开发。**\\n3. **然后过程中，前端和后端协同开发即可。**\\n\\n![](assets/image-20260615225603472.png)\\n\\n这里罗列部分提示词，可以用来做参考\\n\\n\\n\\n后续可以根据需求来实现功能，使用自然语言即可。\\n\\n\\n\\n\\n\\n\\n\\n## 真机预览和真机调试\\n\\n开发过程中可以使用真机预览和真机调试，辅助开发、提升效率。\\n\\n![](assets/image-20260615225739281.png)\\n\\n需要注意的是，如果涉及到调用后端接口，那么可以先不校验合法域名，否则小程序无法调用接口。\\n\\n![](assets/image-20260615225832408.png)\\n\\n## 发布上线全流程\\n\\n如果一切都开发完毕，那么需要做好发布上线的一些准备。\\n\\n发布前，需要登录微信公众平台完成相关信息的登记。\\n\\n![](assets/image-20260615230047478.png)\\n\\n**小程序信息**\\n\\n![](assets/image-20260615230113921.png)\\n\\n---\\n\\n**小程序类目**\\n\\n![](assets/image-20260615230140972.png)\\n\\n---\\n\\n**小程序备案**\\n\\n备案相对麻烦一点，不过跟着指示走即可。\\n\\n\\n\\n**后端部署**\\n\\n后端需要部署在公网服务器上，这样上线后的小程序才能访问。\\n\\n\\n\\n## 结尾\\n\\n最后，由于个人开发的小程序不具备相关资质，因此个人版本的上线失败了。\\n\\n![](assets/image-20260615230346109.png)\\n\\n---\\n\\n![](assets/image-20260615230400781.png)\\n\\n---\\n\\n## 全文总结\\n\\n本文完整记录了使用 **AtomCode**（AI 编程助手）开发微信小程序《谁去呀》的全流程，涵盖了从环境准备到上线发布的每一个关键环节，主要包含以下内容：\\n\\n| 阶段 | 核心步骤 | 要点 |\\n|------|----------|------|\\n| **环境准备** | 下载安装 AtomCode、微信开发者工具 | 注册小程序账号、获取 APPID |\\n| **项目初始化** | 新建小程序工程、生成产品原型图 | 选择云开发或自建后端 |\\n| **协同开发** | 客户端 + 后端并行开发 | 前端优先使用模拟数据，后端后续接入 |\\n| **真机调试** | 真机预览与调试 | 开发时可不校验合法域名，方便调试 |\\n| **发布上线** | 信息登记、类目选择、备案、后端部署 | 个人开发者可能受资质限制无法上线 |\\n\\n**核心亮点：**\\n\\n- **AI 驱动开发**：全程使用 AtomCode 的自然语言对话能力，从生成原型图到编写代码，大幅降低开发门槛。\\n- **前后端协同**：采用小程序端先开发、后端逐步接入的策略，配合模拟数据实现并行开发。\\n- **实用技巧**：每个项目首次执行 `/init` 命令让 AI 熟悉工程，后续用自然语言描述需求即可。\\n\\n**注意事项：** 个人开发者发布小程序时需留意资质要求，部分类目需要企业主体或相关许可证才能通过审核，建议在项目启动前就确认好上线资质。\\n\\n通过本文的流程，即使是个人开发者也能借助 AI 工具快速完成一个小程序从零到发布的全过程，将主要精力集中在产品设计和业务逻辑上。\\n\\n\\n"}'),D={name:"AI人工智能/AtomcCode开发微信小程序全流程/AtomCode开发微信小程序全流程.md"};function z(w,t,F,N,S,T){return o(),a("div",null,[...t[0]||(t[0]=[e("",94)])])}const y=n(D,[["render",z]]);export{V as __pageData,y as default};
